contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public payable test function taking a dummy uint parameter (not used) to satisfy input requirement
    function run(uint dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // record balances before the call
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // attempt the call and record whether it reverted
        bool didRevert;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // After the call: if it did not revert, then C's balance must be 0 and this contract's balance must be at least as large as before
        assert(didRevert || (address(c).balance == 0 && address(this).balance >= beforeThis));
    }

    receive() external payable { }
}

